// Verifies that lib/hosted/signing.ts produces a byte-identical signature to
// the backend's signHostedServiceRequest
// (anvil-app/cloud/backend/src/hosted/service-auth.ts).
//
// The expected vector below was generated by invoking the real backend
// signer under Node type-stripping with these fixed inputs:
//
//   method    POST
//   url       https://sync.anvil.dev/internal/hosted/account
//   body      {"workosClientId":"client_01TEST","workosUserId":"user_01TEST"}
//   audience  anvil-hosted
//   keyId     site-prod-1
//   secret    hosted-secret-vector-0123456789abcdef
//   now       1758000000000
//   requestId req_01JTESTVECTOR00001
//
// Run with: node scripts/verify-hosted-signing.mjs
// (Requires Node >= 22.18 — imports the .ts source via type stripping, so
// the checked code is the exact code the site ships; no duplicated logic.)

import { signHostedRequest } from "../lib/hosted/signing.ts";

const VECTOR = {
  method: "POST",
  pathWithQuery: "/internal/hosted/account",
  body: new TextEncoder().encode(
    JSON.stringify({ workosClientId: "client_01TEST", workosUserId: "user_01TEST" })
  ),
  keyId: "site-prod-1",
  secret: "hosted-secret-vector-0123456789abcdef",
  now: 1758000000000,
  requestId: "req_01JTESTVECTOR00001",
  expectedSignature: "551b96417559b90afdecdaac180264e1c342e17aebf6a4276d6db456a50a1d15"
};

const headers = await signHostedRequest({
  keyId: VECTOR.keyId,
  secret: VECTOR.secret,
  method: VECTOR.method,
  pathWithQuery: VECTOR.pathWithQuery,
  body: VECTOR.body,
  now: VECTOR.now,
  requestId: VECTOR.requestId
});

const failures = [];
if (headers["x-anvil-signature"] !== VECTOR.expectedSignature) {
  failures.push(
    `signature mismatch: got ${headers["x-anvil-signature"]}, want ${VECTOR.expectedSignature}`
  );
}
if (headers["x-anvil-key-id"] !== VECTOR.keyId) failures.push("key id header mismatch");
if (headers["x-anvil-timestamp"] !== String(VECTOR.now)) {
  failures.push("timestamp header mismatch");
}
if (headers["x-anvil-request-id"] !== VECTOR.requestId) failures.push("request id header mismatch");

// A second vector covering a query string: pathname + search is what gets
// signed, so the signature must change when the query does.
const withQuery = await signHostedRequest({
  ...VECTOR,
  pathWithQuery: "/internal/hosted/account?probe=1"
});
if (withQuery["x-anvil-signature"] === headers["x-anvil-signature"]) {
  failures.push("query string is not covered by the signature");
}

if (failures.length > 0) {
  console.error("hosted signing check FAILED");
  for (const failure of failures) console.error(`  - ${failure}`);
  process.exit(1);
}

console.log("hosted signing check passed");
console.log(`  signature: ${headers["x-anvil-signature"]}`);
